  ('befc3ed1-43d5-40e5-93fe-2c07f87c1ba1', 'a8b9c0d1-2e3f-4a23-8b52-6c7d8e9f0a13', null, 'topic'::public.curated_course_node_type, 'Sustainable and Regenerative Tourism', 'Moves beyond minimizing harm toward measurable destination stewardship, local value creation, ecosystem restoration, resource efficiency, and long-term resilience.', 5),
