  ('4791b831-6049-454d-8605-38f271fa2b3d', 'a8b9c0d1-2e3f-4a23-8b52-6c7d8e9f0a13', '0e8e7e36-7722-4910-b9bd-f94d22c74562', 'concept'::public.curated_course_node_type, 'Limits, tradeoffs, and evidence of net benefit', null, 3),
  ('e72dbd86-918c-44d6-a78c-196a816d3f73', 'a8b9c0d1-2e3f-4a23-8b52-6c7d8e9f0a13', null, 'topic'::public.curated_course_node_type, 'Cultural, Heritage, and Indigenous Tourism', 'Plans visitor experiences that protect living culture and heritage, respect rights and ownership, and avoid extractive or inauthentic development.', 6),
