  ('d339d287-ad2c-42dc-9f19-5b14f29a4900', 'a8b9c0d1-2e3f-4a23-8b52-6c7d8e9f0a13', 'e72dbd86-918c-44d6-a78c-196a816d3f73', 'subtopic'::public.curated_course_node_type, 'Rights, ownership, and representation', 'Communities and Indigenous peoples must control how culture, stories, images, knowledge, and sacred places are used.', 1),
