  ('dc25e14c-a140-4cce-bb5d-2b64cf27b924', 'a8b9c0d1-2e3f-4a23-8b52-6c7d8e9f0a13', '5d40acde-890d-4899-a4ae-570e36367cb6', 'concept'::public.curated_course_node_type, 'National, regional, local, and site-level roles', null, 0),
