values
  ('6516ef63-9b7a-4d45-acd4-05ef66d4db84', 'a8b9c0d1-2e3f-4a23-8b52-6c7d8e9f0a13', null, 'topic'::public.curated_course_node_type, 'Destination Economics, Investment, and Project Appraisal', 'Builds the financial and economic reasoning needed to compare projects, incentives, public value, leakage, local linkages, feasibility, and risk.', 10),
